import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readlinkSync, realpathSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { basename, join, sep } from "node:path";
import { findProjectRoot } from "./paths.js";
/**
 * Opt-in `flisk doctor --agents` check (#3128): notes when several coding agents appear to work in
 * one checkout, where they overwrite each other's edits and Flisk's generated files (`.flisk/` and
 * the per-service `.autogenerated` files).
 *
 * Evidence is conservative and read-only:
 * - running agent CLI processes whose working directory is inside the checkout (process names only,
 *   never command arguments, which can carry prompts or keys),
 * - Claude Code session transcripts for this checkout under `~/.claude/projects/`, counted by file
 *   name and mtime only - file contents are never opened,
 * - agent config directories inside the checkout (`.cursor/`, `.claude/`, ...), which show an agent
 *   was used here but do not count toward the "several" threshold on their own.
 *
 * Other agents' session stores either cannot be tied to a checkout without reading file contents
 * (Codex keeps dated rollouts) or do not exist, so they are covered by the process scan instead.
 */
const CHECK_NAME = "Coding agents";
const DEFAULT_RECENT_WINDOW_MS = 24 * 60 * 60 * 1000;
const PROCESS_TIMEOUT_MS = 5000;
/** comm basename (lowercase) to display name. Only session-style CLIs belong here, not IDEs. */
const AGENT_BINARIES = {
    claude: "Claude Code",
    codex: "Codex",
    "cursor-agent": "Cursor",
    gemini: "Gemini CLI",
    aider: "aider",
    opencode: "opencode",
    devin: "Devin",
    copilot: "GitHub Copilot",
    goose: "Goose",
    amp: "Amp",
    droid: "Factory Droid",
    kiro: "Kiro",
    "kiro-cli": "Kiro",
    qwen: "Qwen Code",
    qoder: "Qoder",
    crush: "Crush",
    antigravity: "Antigravity",
};
/** Paths inside a checkout that show an agent tool was used there. */
const AGENT_MARKERS = [
    [".claude", "Claude Code"],
    [".cursor", "Cursor"],
    [".codex", "Codex"],
    [".gemini", "Gemini CLI"],
    [".aider.conf.yml", "aider"],
    [".aider.input.history", "aider"],
    [".opencode", "opencode"],
    [".continue", "Continue"],
    [".windsurf", "Windsurf"],
    [".github/copilot-instructions.md", "GitHub Copilot"],
];
const defaultRunner = (command, args) => execFileSync(command, args, {
    encoding: "utf-8",
    stdio: "pipe",
    timeout: PROCESS_TIMEOUT_MS,
    windowsHide: true,
});
/** `ps -axo pid=,comm=` rows to `{ pid, comm }`; comm may be a path, matched by basename later. */
function listProcesses(run, platform) {
    if (platform === "win32")
        return [];
    let output;
    try {
        output = run("ps", ["-axo", "pid=,comm="]);
    }
    catch {
        return [];
    }
    const processes = [];
    for (const line of output.split(/\r?\n/)) {
        const trimmed = line.trim();
        if (!trimmed)
            continue;
        const gap = trimmed.indexOf(" ");
        if (gap <= 0)
            continue;
        const pid = Number(trimmed.slice(0, gap));
        const comm = trimmed.slice(gap + 1).trim();
        if (!Number.isInteger(pid) || pid <= 0 || !comm)
            continue;
        processes.push({ pid, comm });
    }
    return processes;
}
function agentProcesses(processes) {
    const agents = [];
    for (const { pid, comm } of processes) {
        const product = AGENT_BINARIES[basename(comm).toLowerCase()];
        if (product)
            agents.push({ pid, product });
    }
    return agents;
}
/**
 * Working directory per pid. Linux reads `/proc/<pid>/cwd` (no spawn); other unixes take one
 * `lsof -a -p <pids> -d cwd -Fn` call. Any failure yields an empty/partial map, which the caller
 * treats as "cannot attribute" rather than guessing.
 */
function listProcessCwdsDefault(pids, platform, run) {
    const cwds = new Map();
    if (pids.length === 0)
        return cwds;
    if (platform === "linux") {
        for (const pid of pids) {
            try {
                const target = readlinkSync(`/proc/${pid}/cwd`);
                if (target)
                    cwds.set(pid, target);
            }
            catch {
                // Process exited or no procfs: leave it unattributed.
            }
        }
        return cwds;
    }
    try {
        const output = run("lsof", ["-a", "-p", pids.join(","), "-d", "cwd", "-Fn"]);
        let currentPid = null;
        for (const line of output.split(/\r?\n/)) {
            if (line.startsWith("p")) {
                const pid = Number(line.slice(1));
                currentPid = Number.isInteger(pid) && pid > 0 ? pid : null;
            }
            else if (line.startsWith("n") && currentPid !== null) {
                cwds.set(currentPid, line.slice(1));
                currentPid = null;
            }
        }
    }
    catch {
        // lsof missing or failed: cwds stay empty.
    }
    return cwds;
}
function gitToplevel(dir, run) {
    try {
        const top = run("git", ["-C", dir, "rev-parse", "--show-toplevel"]).trim();
        return top.length > 0 ? top : null;
    }
    catch {
        return null;
    }
}
/** Claude Code names `~/.claude/projects/<dir>` by replacing every non-alphanumeric char with "-". */
export function claudeProjectSlug(dir) {
    return dir.replace(/[^a-zA-Z0-9]/g, "-");
}
/** readdir + stat only: names, types and mtimes, never file contents. */
function defaultListSessionFiles(dir) {
    const entries = [];
    for (const dirent of readdirSync(dir, { withFileTypes: true })) {
        if (!dirent.isFile() || !dirent.name.endsWith(".jsonl"))
            continue;
        try {
            entries.push({ name: dirent.name, mtimeMs: statSync(join(dir, dirent.name)).mtimeMs });
        }
        catch {
            // Vanished between readdir and stat.
        }
    }
    return entries;
}
function isInsideDir(path, root) {
    if (root === sep)
        return path === root;
    return path === root || path.startsWith(root.endsWith(sep) ? root : root + sep);
}
function uniqueRealpaths(dirs, toReal) {
    const seen = new Set();
    const out = [];
    for (const dir of dirs) {
        const real = toReal(dir);
        if (!seen.has(real)) {
            seen.add(real);
            out.push(real);
        }
    }
    return out;
}
function windowLabel(windowMs) {
    if (windowMs % 3_600_000 === 0)
        return `${windowMs / 3_600_000}h`;
    return `${Math.round(windowMs / 60_000)}m`;
}
export function checkCodingAgents(options = {}) {
    const platform = options.platform ?? process.platform;
    if (platform === "win32") {
        return {
            name: CHECK_NAME,
            didPass: true,
            isSkipped: true,
            message: "Coding-agent scan needs ps/lsof and is skipped on Windows",
        };
    }
    const run = options.run ?? defaultRunner;
    const now = options.now ?? Date.now();
    const windowMs = options.recentWindowMs ?? DEFAULT_RECENT_WINDOW_MS;
    const exists = options.pathExists ?? existsSync;
    const home = options.homeDir ?? homedir();
    const realpath = options.realpath ??
        ((path) => {
            try {
                return realpathSync(path);
            }
            catch {
                return path;
            }
        });
    const toReal = (path) => {
        try {
            return realpath(path);
        }
        catch {
            return path;
        }
    };
    const listSessionFiles = options.listSessionFiles ?? defaultListSessionFiles;
    const listCwds = options.listProcessCwds ?? ((pids) => listProcessCwdsDefault(pids, platform, run));
    const startDir = options.startDir ?? process.cwd();
    const projectRoot = options.projectRoot !== undefined ? options.projectRoot : findProjectRoot(startDir);
    // The checkout is the git worktree when there is one (agents live at its root and each linked
    // worktree stays separate); the project root and cwd widen session/marker coverage for projects
    // that sit inside a larger repo or are not git checkouts at all.
    const gitRoot = gitToplevel(projectRoot ?? startDir, run);
    const candidates = uniqueRealpaths([gitRoot, projectRoot, startDir].filter((dir) => Boolean(dir)), toReal);
    const containmentRoot = toReal(gitRoot ?? projectRoot ?? startDir);
    const agentProcs = agentProcesses(listProcesses(run, platform));
    const cwds = listCwds(agentProcs.map((agent) => agent.pid));
    const runningByProduct = new Map();
    let runningAgents = 0;
    for (const agent of agentProcs) {
        const cwd = cwds.get(agent.pid);
        if (!cwd || !isInsideDir(toReal(cwd), containmentRoot))
            continue;
        runningAgents++;
        runningByProduct.set(agent.product, (runningByProduct.get(agent.product) ?? 0) + 1);
    }
    let recentSessions = 0;
    const seenSessionDirs = new Set();
    for (const dir of candidates) {
        const sessionDir = join(home, ".claude", "projects", claudeProjectSlug(dir));
        if (seenSessionDirs.has(sessionDir))
            continue;
        seenSessionDirs.add(sessionDir);
        let files;
        try {
            files = listSessionFiles(sessionDir);
        }
        catch {
            continue;
        }
        for (const file of files) {
            if (now - file.mtimeMs <= windowMs)
                recentSessions++;
        }
    }
    const markerProducts = new Set();
    for (const dir of candidates) {
        for (const [relative, product] of AGENT_MARKERS) {
            if (exists(join(dir, relative)))
                markerProducts.add(product);
        }
    }
    const activeProducts = [
        ...new Set([...runningByProduct.keys(), ...(recentSessions > 0 ? ["Claude Code"] : [])]),
    ].sort((a, b) => a.localeCompare(b));
    const products = [...new Set([...activeProducts, ...markerProducts])].sort((a, b) => a.localeCompare(b));
    const agents = Math.max(runningAgents, recentSessions);
    const strict = options.strict ?? false;
    const evidence = [];
    if (runningAgents > 0) {
        const names = [...runningByProduct.keys()].sort((a, b) => a.localeCompare(b)).join(", ");
        evidence.push(`${runningAgents} running process${runningAgents === 1 ? "" : "es"} (${names})`);
    }
    if (recentSessions > 0) {
        evidence.push(`${recentSessions} Claude Code session file${recentSessions === 1 ? "" : "s"} modified in the last ${windowLabel(windowMs)}`);
    }
    const observed = {
        kind: "coding-agents",
        agents,
        runningAgents,
        recentSessions,
        recentWindowMs: windowMs,
        products,
        runningByProduct: Object.fromEntries(runningByProduct),
        checkoutRoots: candidates,
    };
    if (agents >= 2) {
        return {
            name: CHECK_NAME,
            didPass: !strict,
            isWarning: !strict,
            message: `${agents} coding agents appear to work in this checkout: ${evidence.join("; ")}. Agents that share one checkout overwrite each other's edits and Flisk's generated files (.flisk/, services/**/.autogenerated).`,
            fix: "Run each agent in its own git worktree (git worktree add ../<dir> -b <branch>), or install Run My Agents (https://github.com/flisk-sh/run-my-agents) to warn when edits overlap.",
            observed,
        };
    }
    if (agents === 1) {
        return {
            name: CHECK_NAME,
            didPass: true,
            message: `1 coding agent detected here (${evidence.join("; ")}); several agents in one checkout can overwrite each other's edits and Flisk's generated files.`,
            observed,
        };
    }
    return {
        name: CHECK_NAME,
        didPass: true,
        message: markerProducts.size > 0
            ? `No active coding agents detected here; found config for ${[...markerProducts].sort((a, b) => a.localeCompare(b)).join(", ")}`
            : "No coding agents detected in this checkout",
        observed,
    };
}
